import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class LittleCLoves3II {
    static class FastScanner {
        private final BufferedReader in;

        FastScanner(BufferedReader in) {
            this.in = in;
        }

        private int read() {
            try {
                return in.read();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        private boolean delim(int c) {
            return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
        }

        int nextInt() {
            int c = read();
            while (c != -1 && delim(c)) {
                c = read();
            }

            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = read();
            }

            int value = 0;
            while (c != -1 && !delim(c)) {
                value = value * 10 + (c - '0');
                c = read();
            }

            return neg ? -value : value;
        }
    }

    public static void main(String[] args) {
        FastScanner in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        long n = in.nextInt();
        long m = in.nextInt();

        if (n > m) {
            long tmp = n;
            n = m;
            m = tmp;
        }

        long ans;
        if (n == 1) {
            ans = m / 6 * 6 + Math.max(m % 6 - 3, 0) * 2;
        } else if (n == 2) {
            switch ((int) m) {
                case 2:
                    ans = 0;
                    break;
                case 3:
                    ans = 4;
                    break;
                case 7:
                    ans = 12;
                    break;
                default:
                    ans = n * m;
                    break;
            }
        } else {
            ans = n * m / 2 * 2;
        }

        System.out.println(ans);
    }
}
